scwin.trigger4_onclick = function(e) {
    scwin.init();
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 하단의 set버튼을 클릭 후 세로스크롤을 끝까지 내린다.
    //1. Run the sample file, click the set button at the bottom, and then end the vertical scroll.
    //Verify step 1. The filterBox at the bottom of the grid is not covered but is normally visible.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1').setTopRowIndex(25)");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_main_div').css('bottom') == '44px'", "true");
    WebSquare.wUnit.addCommand("assert", "Math.abs(parseInt(WebSquare.wUnit.getJq('#grid1_main_div').css('bottom'), 10) - 44) <= 1", "true");	
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_groupbyFilterBox_div').css('bottom') == '0px'", "true");
	WebSquare.wUnit.addCommand("assert", "Math.abs(parseInt(WebSquare.wUnit.getJq('#grid1_groupbyFilterBox_div').css('bottom'), 10) - 0) <= 1", "true");	
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

